"""Approved registry gates; no full production batch is generated by tests.

Named geometry is checked against its explicit point-cone/force semantics,
not an exported status list. Pure rationals must fail binary64 encoding.
"""
from fractions import Fraction as Q

import pytest

from eab.kernel2d.contacts import assemble_contact_set2, constraint_matrix
from eab.kernel2d.mobility import first_order_free_twists
from eab.kernel2d.sensitivity import evaluate_sensitivity2
from eab.kernel2d.statics import limit_load_ideal_exact_2d, critical_parameter
from tia2d_cases import input_record, input_audit
from tia2d_export import (registered_specs, python_only_specs, materialize,
                         _sensitivity_factory, _python_only, run_export)


def _spec(case_id):
    return next(spec for spec in registered_specs() if spec["case_id"] == case_id)


def test_registry_covers_original_91_and_23_contract_roles_without_duplicate_ids():
    specs = registered_specs()
    assert len(specs) == len({spec["case_id"] for spec in specs}) == 114
    assert sum(spec["registry_kind"] == "beam" for spec in specs) == 48
    assert sum(spec["registry_kind"] == "regression" for spec in specs) == 7
    assert sum(spec["registry_kind"] == "morphology" for spec in specs) == 36
    assert sum(spec["registry_kind"] == "coverage" for spec in specs) == 8
    assert sum(spec["registry_kind"] == "single_body" for spec in specs) == 15
    assert {spec["family"] for spec in specs} == {"TIA-G1", "TIA-G2", "TIA-G3", "TIA-G4", "TIA-G5", "named_regression", "contract_coverage"}
    assert len(python_only_specs()) == 2
    assert not ({spec["case_id"] for spec in specs} & {spec["case_id"] for spec in python_only_specs()})


@pytest.mark.parametrize("case_id", ("g1_slender", "g5_n7_mu0", "TIA-G2-A0-W0",
    "TIA-G3-A3-W2", "TIA-G4-A2-W1", "regression_f_convex_in_notch"))
def test_representative_registry_inputs_are_lossless_binary64_with_explicit_boundaries(case_id):
    model, _ = materialize(_spec(case_id))
    encoded = input_record(model)
    audit = input_audit(model, encoded)
    assert audit["lossless_binary64"] and encoded["completeness"] == "complete"
    assert all("dof_mask" in body and "dof_anchor_bits" in body and "boundary_type" in body for body in encoded["bodies"])
    assert any(row["state"] == "CONTACT" for row in audit["exact_pair_states"])


def test_registered_a_retains_two_segments_four_endpoint_constraints():
    model, _ = materialize(_spec("regression_a_saw"))
    contacts = assemble_contact_set2(model)
    assert contacts.status == "RESOLVED" and len(contacts.segments) == 2 and len(contacts.constraints) == 4
    assert {c.point for c in contacts.constraints} == {(0, 0), (1, 1), (0, 2)}


@pytest.mark.parametrize("case_id", ("regression_b_bare_vv", "regression_e_mixed_vv_edge"))
def test_registered_b_and_e_remain_unresolved_in_both_public_apis(case_id):
    model, _ = materialize(_spec(case_id))
    contacts = assemble_contact_set2(model)
    assert contacts.status == first_order_free_twists(model, contacts).mathematical_status == "MECHANICAL_UNRESOLVED"
    assert contacts.reachable_witnesses
    if case_id.endswith("mixed_vv_edge"):
        matrix, dofs = constraint_matrix(model, contacts.constraints)
        assert dofs == ((0, 0), (0, 1), (0, 2))
        assert all(sum(a * b for a, b in zip(row, (1, 1, Q(3, 2)))) >= 0 for row in matrix)
        assert any(p.point == (0, 1) for p in contacts.unresolved)


def test_registered_c_contains_actual_twist_unreachability_certificate():
    model, _ = materialize(_spec("regression_c_redundant_vv"))
    contacts = assemble_contact_set2(model)
    assert contacts.status == "RESOLVED" and len(contacts.redundancy_certificates) == 1
    proof = contacts.redundancy_certificates[0]
    assert proof.unreachable and len(proof.dofs) == 3
    assert all(sum(a * b for a, b in zip(column, proof.multipliers)) == 0 for column in zip(*proof.matrix))
    assert sum(a * b for a, b in zip(proof.rhs, proof.multipliers)) == 1


@pytest.mark.parametrize("case_id,value", (("regression_d_flush_mu0", Q(0)), ("regression_d_flush_mu025", Q(1, 2))))
def test_registered_d_has_both_exact_required_capacities(case_id, value):
    model, _ = materialize(_spec(case_id))
    result = limit_load_ideal_exact_2d(model)
    assert result.status == "OPTIMAL" and result.exact_value == value


def test_registered_f_uses_only_two_notch_normals_without_edge_overlap():
    model, _ = materialize(_spec("regression_f_convex_in_notch"))
    contacts = assemble_contact_set2(model)
    assert contacts.status == "RESOLVED" and contacts.segments == ()
    assert len(contacts.points) == 1 and contacts.points[0].fp_type == "CONVEX"
    assert {c.normal for c in contacts.constraints} == {(2, 0), (0, 2)}


def test_g5_factory_uses_existing_problem_for_pressure_and_shared_height():
    spec = _spec("g5_n3_mu1")
    model, metadata = materialize(spec)
    result = limit_load_ideal_exact_2d(model)
    requests = _sensitivity_factory(spec, model, metadata)(result, None)
    assert {request["parameter"] for request in requests} == {"P", "h"}
    for request in requests:
        assert request["problem"] is result.problem
        derivative = evaluate_sensitivity2(result, request["seed"], parameter=request["parameter"])
        assert derivative.left_derivative == derivative.right_derivative == {"P": Q(1, 2), "h": Q(0)}[request["parameter"]]


def test_g1_factory_constructs_shared_threshold_t_and_h_seeds_not_finite_differences():
    spec = _spec("g1_slender")
    model, metadata = materialize(spec)
    result = limit_load_ideal_exact_2d(model)
    critical = critical_parameter(model, max_steps=10)
    requests = _sensitivity_factory(spec, model, metadata)(result, critical)
    assert {request["parameter"] for request in requests} == {"t", "h"}
    for request in requests:
        derivative = evaluate_sensitivity2(critical, request["seed"], parameter=request["parameter"])
        assert derivative.left_derivative == derivative.right_derivative == {"t": Q(15, 16), "h": -Q(17, 32)}[request["parameter"]]


@pytest.mark.parametrize("spec", python_only_specs())
def test_python_only_registry_never_silently_rounds_exact_rational_input(spec):
    model, _ = materialize(spec)
    with pytest.raises(ValueError, match="non-binary64"):
        input_record(model)


def test_python_only_diagnostic_has_explicit_non_cpp_format_and_original_rationals():
    value = _python_only(python_only_specs()[0], 2)
    assert value["diagnostic_format"] == "tia2d.python-only-diagnostic.v1"
    assert value["case_v1_export"] is value["cpp_input"] is False
    assert value["parameters"]["kwargs"]["t"] == "1/10"
    assert "vertices_xy_bits" not in str(value["assembly"])


def test_factory_preserves_crossing_labels_and_does_not_divide_by_zero_slope():
    tie = _spec("g5_n3_mu2")
    model, metadata = materialize(tie)
    limit = limit_load_ideal_exact_2d(model)
    requests = _sensitivity_factory(tie, model, metadata)(limit, None)
    assert all("tied_labels" not in r for r in requests)
    assert all(r["display_note"]["labels"] == ["sliding", "hinging"] for r in requests)
    zero = _spec("g1_koureas_h0_t0")
    model, metadata = materialize(zero)
    limit = limit_load_ideal_exact_2d(model)
    critical = critical_parameter(model, max_steps=10)
    request = next(r for r in _sensitivity_factory(zero, model, metadata)(limit, critical) if r["parameter"] == "t")
    assert request["negative_direction_valid"] is False
    assert any(value for row in request["seed"].dA for value in row)


def test_export_failure_invalidates_entire_root_and_refuses_resume(monkeypatch, tmp_path):
    import json
    import tia2d_export as module
    def changed_source(*args, **kwargs):
        raise RuntimeError("source changed during batch")
    monkeypatch.setattr(module, "export_cases", changed_source)
    target = tmp_path / "invalidated_batch"
    with pytest.raises(RuntimeError, match="source changed"):
        run_export(target, selected_ids=["regression_b_bare_vv"], include_python_only=False, _output_root=tmp_path)
    progress = json.loads((target / "progress.json").read_text(encoding="utf-8"))
    assert progress["state"] == "INVALIDATED" and progress["valid"] is False and progress["completed"] == 0
    with pytest.raises(ValueError, match="NEW T1a_evidence"):
        run_export(target, selected_ids=["regression_b_bare_vv"], include_python_only=False, _output_root=tmp_path)


def test_export_output_injection_cannot_escape_declared_test_domain(tmp_path):
    allowed = tmp_path / "allowed"
    outside = tmp_path / "outside"
    with pytest.raises(ValueError, match="NEW T1a_evidence"):
        run_export(outside, selected_ids=["regression_b_bare_vv"], _output_root=allowed)
    assert not outside.exists()


@pytest.mark.parametrize("case_id", ("g1_slender", "g1_unreversed_t2", "g1_reverse_i1_t2",
    "g1_koureas_h0_t0", "g5_n3_mu1", "g5_n3_mu2", "g5_n5_mu3",
    "TIA-G2-A2-W1", "TIA-G3-A2-W1", "TIA-G4-A2-W1"))
def test_geometry_vertex_load_anchor_jets_rebuild_every_non_mu_seed(case_id):
    """Original IDs and exact edge differences independently rebuild dA/db/dc.

    No finite differences or family contact-seed function is used by the
    propagation path. The production factory checks this again on every
    formal query, including all 166 original non-mu query roles.
    """
    from tia2d_seed import propagate_geometry_seed
    spec = _spec(case_id)
    model, geometry = materialize(spec)
    result = limit_load_ideal_exact_2d(model)
    critical = critical_parameter(model, max_steps=10)
    requests = _sensitivity_factory(spec, model, geometry)(result, critical)
    assert requests
    for request in requests:
        jet = request["geometry_seed"]
        assert jet["vertex_ids"] == sorted(jet["vertex_ids"])
        assert jet["parameters"] == [request["parameter"]]
        assert propagate_geometry_seed(request["problem"], jet) == request["seed"]


def test_geometry_jet_propagation_has_teeth_for_shared_vertices_loads_and_anchors():
    from copy import deepcopy
    from tia2d_seed import propagate_geometry_seed
    spec = _spec("g5_n3_mu1")
    model, geometry = materialize(spec)
    result = limit_load_ideal_exact_2d(model)
    requests = _sensitivity_factory(spec, model, geometry)(result, None)
    height = next(request for request in requests if request["parameter"] == "h")
    bad = deepcopy(height["geometry_seed"])
    bad["vertices"][0][0][1] = "1/1"
    with pytest.raises(ValueError, match="shared vertex"):
        propagate_geometry_seed(result.problem, bad)
    pressure = next(request for request in requests if request["parameter"] == "P")
    bad = deepcopy(pressure["geometry_seed"])
    bad["dead"][0][-1][0] = "0/1"
    assert propagate_geometry_seed(result.problem, bad) != pressure["seed"]


@pytest.mark.parametrize("name,status", (("farkas_free_dead", "INFEASIBLE"),
    ("separated", "OPTIMAL"), ("overlap", "OVERLAP"),
    ("completeness_unknown", "UNPROVED")))
def test_approved_contract_roles_have_exact_expected_limit_status(name, status):
    model, _ = materialize(_spec("coverage_" + name))
    result = limit_load_ideal_exact_2d(model)
    assert result.mathematical_status == status
    if status == "INFEASIBLE":
        assert result.farkas and sum(a * b for a, b in zip(result.problem.b, result.farkas)) != 0


@pytest.mark.parametrize("family", ("TIA-G1", "TIA-G5", "TIA-G2", "TIA-G3", "TIA-G4"))
@pytest.mark.parametrize("index", (1, 2, 3))
def test_formal_single_body_roles_free_only_the_named_body(family, index):
    model, _ = materialize(_spec("single_" + family + "_body" + str(index)))
    assert [i for i, body in enumerate(model.bodies) if any(body.dof_mask)] == [index]
    result = first_order_free_twists(model)
    assert result.dofs == tuple((index, k) for k in (0, 1, 2))
    assert result.mathematical_status == ("ZERO_CONE" if family in ("TIA-G2", "TIA-G3", "TIA-G4") else "NONZERO_CONE")


def test_geometry_anchor_jet_changes_actual_rotation_projection_not_reference():
    """Direct product-rule oracle: d(moment at anchor)=-danchor cross force."""
    from eab.kernel2d.assembly import Assembly2, Body2
    from tia2d_seed import geometry_seed, propagate_geometry_seed
    a = Body2.from_vertices("A", ((0, 0), (1, 0), (1, 1), (0, 1)),
        reference_point=(7, -4), dof_anchor=(Q(1, 2), Q(1, 2)), dead=(1, 0, 4), live=(0, -1, 7))
    b = Body2.from_vertices("B", ((1, 0), (2, 0), (2, 1), (1, 1)),
        reference_point=(-3, 2), dof_anchor=(1, 0), boundary_type="FIXED_BODY", dof_mask=(0, 0, 0))
    model = Assembly2((a, b), ((0, 1),), "complete")
    problem = limit_load_ideal_exact_2d(model).problem
    jet = geometry_seed(model, "anchor_y", anchors={"A": (0, 1)})
    seed = propagate_geometry_seed(problem, jet)
    assert seed.dA[0] == seed.dA[1] == (Q(0),) * len(problem.c)
    assert seed.dA[2] == (-Q(1),) * (len(problem.c) - 1) + (Q(0),)
    assert seed.db == (Q(0), Q(0), -Q(1))
    assert model.bodies[0].reference_point == (7, -4)


@pytest.mark.parametrize("case_id,keys", (("regression_d_flush_mu025", {"N", "h", "P", "widths"}),
    ("single_TIA-G1_body2", {"t", "h", "orientation"}),
    ("single_TIA-G3_body2", {"A", "wavelength"})))
def test_family_parameter_metadata_covers_regression_and_single_roles(case_id, keys):
    from tia2d_export import family_parameters
    spec = _spec(case_id)
    model, _ = materialize(spec)
    assert keys <= family_parameters(spec, model).keys()
